  app.use('/api/appointments', appointmentsRouter);
  app.use('/api/admin', adminStatsRouter);
  app.use('/api/display', displayRouter);
  app.use('/api', handleErrors);
  setInterval(convertDueAppointments, CONVERSION_INTERVAL_MS).unref();
}

