import { Link } from 'react-router-dom';
import { formatDuration } from '../../shared/labels';
import type { TicketView } from '../../shared/types';
import { StatusBadge } from './StatusBadge';

interface TicketResultProps {
  ticket: TicketView;
  onBookAnother: () => void;
}

