import { formatDateTime } from '../../shared/labels';
import { StatusBadge } from './StatusBadge';

export type HistoryEntry =
  | { kind: 'ticket'; id: string; number: string; status: Parameters<typeof StatusBadge>[0] & { kind?: 'ticket' }; branch: string; service: string; time: string; sortKey: string }
  | { kind: 'appointment'; id: string; status: Parameters<typeof StatusBadge>[0] & { kind: 'appointment' }; branch: string; service: string; time: string; sortKey: string };

interface HistoryRowProps {
  entry: HistoryEntry;
}

export function HistoryRow({ entry }: HistoryRowProps) {
  return (
    <li
      className="data-row history-row"
      data-testid="history-row"
      data-id={entry.id}
      data-number={entry.kind === 'ticket' ? entry.number : undefined}
    >
      <span className="cell cell-strong" data-testid="history-label">
        {entry.kind === 'ticket' ? entry.number : 'Appointment'}
      </span>
      <span className="cell">
        <StatusBadge {...entry.status} testId="history-status" />
      </span>
      <span className="cell" data-testid="history-branch">
        {entry.branch}
      </span>
      <span className="cell" data-testid="history-service">
        {entry.service}
      </span>
      <span className="cell muted" data-testid="history-time">
        {formatDateTime(entry.time)}
      </span>
    </li>
  );
}

