          <button
            type="button"
            className="btn btn-danger-outline btn-sm"
            data-testid="waiting-cancel"
            aria-label={`Cancel ${ticket.ticketNumber}`}
            onClick={() => onCancel(ticket)}
          >
            Cancel
          </button>
        </li>
      ))}
    </ul>
  );
}

