input.content:
h1,
h2,
h3,
p {
  margin: 0;
}

.shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  min-height: 56px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-4);
  padding: var(--space-2) var(--space-4);
  background: var(--color-nav-bg);
  color: var(--color-nav-text);
}

.brand {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
}

.topbar-clock {
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
}

.persona {
  margin-left: auto;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--font-size-sm);
}

.persona select {
  height: var(--control-height-sm);
  min-width: 0;
  max-width: 100%;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-border-strong);
  padding: 0 var(--space-2);
  background: var(--color-surface);
  color: var(--color-text);
  font: inherit;
}

.current-user {
  font-weight: var(--font-weight-medium);
}

.shell-body {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.main-nav {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  padding: var(--space-2) var(--space-4);
  background: var(--color-nav-bg);
}

.nav-link {
  min-height: var(--control-min-target);
  display: inline-flex;
  align-items: center;
  padding: 0 var(--space-4);
  border-radius: var(--radius-sm);
  color: var(--color-nav-text);
  text-decoration: none;
  font-weight: var(--font-weight-medium);
}

.nav-link:hover {
  background: rgba(255, 255, 255, 0.1);
}

.nav-link[aria-current='page'] {
  background: var(--color-nav-active-bg);
  color: var(--color-text-inverse);
}

.content {
  width: 100%;
  max-width: var(--width-content);
  margin: 0 auto;
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.shell-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-4);
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
}

.shell-footer .muted {
  flex: 1 1 200px;
}

.toast-region {
  position: fixed;
  left: 50%;
  bottom: var(--space-5);
  transform: translateX(-50%);
  z-index: 60;
  max-width: calc(100vw - 2 * var(--space-4));
}

.toast {
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  background: var(--color-success-bg);
  color: var(--color-success);
  border: 1px solid var(--color-success);
  box-shadow: var(--shadow-raised);
  font-weight: var(--font-weight-medium);
}

.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-4);
  background: rgba(19, 36, 58, 0.55);
}

.overlay-side {
  justify-content: flex-end;
  align-items: stretch;
  padding: 0;
}

.dialog {
  width: min(var(--width-dialog), 100%);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-5);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  box-shadow: var(--shadow-raised);
}

.side-panel {
  width: min(var(--width-form), 100%);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-5);
  overflow-y: auto;
  background: var(--color-surface);
  box-shadow: var(--shadow-raised);
}

@media (min-width: 768px) {
  .content {
    padding: var(--space-5);
  }
}

@media (min-width: 1024px) {
  .shell-body {
    flex-direction: row;
  }

  .main-nav {
    width: var(--width-sidebar);
    flex-shrink: 0;
    flex-direction: column;
    flex-wrap: nowrap;
    padding: var(--space-4) var(--space-3);
  }

  .shell-body .content {
    flex: 1;
    min-width: 0;
  }
}

